-- Run only on QA. Synthetic identities, account balances, events and all test changes roll back.
begin;
create temp table qa_debtor_audit_results(name text,passed boolean) on commit drop;
create function pg_temp.audit_check(label text,condition boolean) returns void language plpgsql as $$begin
 if condition is not true then raise exception 'QA assertion failed: %',label;end if;
 insert into qa_debtor_audit_results values(label,true);
end $$;
create function pg_temp.fail_qa_receipt() returns trigger language plpgsql as $$begin raise exception 'injected_qa_receipt_failure';end $$;
create function pg_temp.fail_qa_audit() returns trigger language plpgsql as $$begin raise exception 'injected_qa_audit_failure';end $$;
do $$
declare employee uuid:=gen_random_uuid();manager uuid:=gen_random_uuid();support uuid:=gen_random_uuid();unknown uuid:=gen_random_uuid();u uuid;s uuid;claims jsonb:='{}';label text;r text;d uuid;key uuid:=gen_random_uuid();payment uuid;denied boolean;before_report jsonb;after_report jsonb;ledger jsonb;cash_before numeric;cash_after numeric;events_before int;entries_before int;receipts_before int;product uuid:=gen_random_uuid();body jsonb;sale uuid;return_req uuid;sale_doc uuid;operation_id uuid;
begin
 for label,u,r in select * from(values('employee',employee,'employee'),('manager',manager,'system_admin'),('support',support,'technical_support'),('unknown',unknown,null::text))x(label,u,r) loop
  s:=gen_random_uuid();
  insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values(u,'authenticated','authenticated','qa-audit-'||u||'@example.invalid',now(),case when r is null then '{}'::jsonb else jsonb_build_object('system_role',r) end,'{}',now(),now());
  insert into auth.sessions(id,user_id,aal,created_at,updated_at,not_after) values(s,u,'aal1',now(),now(),now()+interval '1 hour');
  claims:=claims||jsonb_build_object(label,jsonb_build_object('sub',u,'session_id',s,'role','authenticated'));
 end loop;
 foreach label in array array['debtors','debtor_entries','debtor_cash_receipts','audit_events'] loop
  perform pg_temp.audit_check('no direct API access to '||label,not has_table_privilege('authenticated','pharmacy_qa_private.'||label,'SELECT,INSERT,UPDATE,DELETE'));
 end loop;
 perform pg_temp.audit_check('private audit writer is not callable',not has_function_privilege('authenticated','pharmacy_qa_private.write_audit(text,text,text,jsonb,uuid)','execute'));
 foreach label in array array['support','unknown','anonymous'] loop
  perform set_config('request.jwt.claims',coalesce(claims->label,'{}')::text,true);
  denied:=false;begin perform public.qa_create_debtor('QA',null,null,null,gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
  perform pg_temp.audit_check(label||' cannot create debtors',denied);
  denied:=false;begin perform public.qa_list_debtors();exception when insufficient_privilege then denied:=true;end;
  perform pg_temp.audit_check(label||' cannot read debtor accounts',denied);
  denied:=false;begin perform public.qa_debtor_ledger(gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
  perform pg_temp.audit_check(label||' cannot read a ledger',denied);
  denied:=false;begin perform public.qa_record_debtor_payment(gen_random_uuid(),1,null,'cash',gen_random_uuid());exception when insufficient_privilege then denied:=true;end;
  perform pg_temp.audit_check(label||' cannot record payments',denied);
  denied:=false;begin perform public.qa_security_audit();exception when insufficient_privilege then denied:=true;end;
  perform pg_temp.audit_check(label||' cannot read security events',denied);
 end loop;
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 d:=public.qa_create_debtor('QA debtor '||employee,'000-QA','synthetic only','test only',key);
 perform pg_temp.audit_check('employee creates debtor directly',d is not null);
 perform pg_temp.audit_check('create retry returns same debtor',public.qa_create_debtor('QA debtor '||employee,'000-QA','synthetic only','test only',key)=d);
 denied:=false;begin perform public.qa_create_debtor('QA debtor '||employee,'000-QA','synthetic only','test only',gen_random_uuid());exception when unique_violation then denied:=true;end;
 perform pg_temp.audit_check('duplicate debtor is not created',denied);
 denied:=false;begin perform public.qa_create_debtor('different',null,null,null,key);exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.audit_check('changed payload cannot replay creation key',denied);
 perform pg_temp.audit_check('new debtor starts at zero balance',(public.qa_debtor_ledger(d)->>'balance')::numeric=0);
 denied:=false;begin perform public.qa_record_debtor_payment(d,1,null,'cash',gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.audit_check('zero-balance account cannot be overpaid',denied);
 perform pg_temp.audit_check('creation is logged with actual actor',exists(select 1 from pharmacy_qa_private.audit_events where action='debtors_insert' and entity_id=d::text and actor_id=employee and actor_role='employee' and details->>'source'='server_transaction'));
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);
 -- Fixture debt only. No employee endpoint may insert a charge or opening balance.
 insert into pharmacy_qa_private.debtor_entries(debtor_id,kind,amount,actor_id,request_id,notes,created_at) values(d,'charge',100,manager,gen_random_uuid(),'synthetic fixture charge',now()-interval '1 day');
 before_report:=public.qa_sandbox_report();select coalesce(sum((x->>'amount')::numeric),0) into cash_before from jsonb_array_elements(before_report->'balances')x where x->>'kind'='cash' and x->>'currency'='SYP';
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 perform pg_temp.audit_check('employee can list debtor balance',exists(select 1 from jsonb_array_elements(public.qa_list_debtors('QA debtor '||employee))x where x->>'id'=d::text and (x->>'balance')::numeric=100));
 ledger:=public.qa_debtor_ledger(d);perform pg_temp.audit_check('employee can open detailed account',(ledger->>'balance')::numeric=100 and jsonb_array_length(ledger->'transactions')=1);
 key:=gen_random_uuid();payment:=public.qa_record_debtor_payment(d,30,'QA collection','cash',key);
 perform pg_temp.audit_check('cash payment reduces debt to 70',(public.qa_debtor_ledger(d)->>'balance')::numeric=70);
 perform pg_temp.audit_check('cash receipt linked to same payment',exists(select 1 from pharmacy_qa_private.debtor_cash_receipts where entry_id=payment and amount=30 and currency='SYP'));
 perform pg_temp.audit_check('payment replay returns same entry',public.qa_record_debtor_payment(d,30,'QA collection','cash',key)=payment);
 perform pg_temp.audit_check('payment replay does not deduct twice',(public.qa_debtor_ledger(d)->>'balance')::numeric=70);
 denied:=false;begin perform public.qa_record_debtor_payment(d,31,'QA collection','cash',key);exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.audit_check('changed payment cannot reuse key',denied);
 foreach r in array array['0','-1','NaN','100000001','0.00001'] loop
  denied:=false;begin perform public.qa_record_debtor_payment(d,r::numeric,null,'cash',gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;
  perform pg_temp.audit_check('invalid payment rejected: '||r,denied);
 end loop;
 perform public.qa_record_debtor_payment(d,10,'noncash fixture','other',gen_random_uuid());
 perform pg_temp.audit_check('noncash payment reduces debt without cash receipt',(public.qa_debtor_ledger(d)->>'balance')::numeric=60 and (select count(*)=1 from pharmacy_qa_private.debtor_cash_receipts r join pharmacy_qa_private.debtor_entries e on e.id=r.entry_id where e.debtor_id=d));
 select count(*) into events_before from pharmacy_qa_private.audit_events;select count(*) into entries_before from pharmacy_qa_private.debtor_entries;select count(*) into receipts_before from pharmacy_qa_private.debtor_cash_receipts;
 execute 'create trigger qa_test_fail_receipt before insert on pharmacy_qa_private.debtor_cash_receipts for each row execute function pg_temp.fail_qa_receipt()';
 denied:=false;begin perform public.qa_record_debtor_payment(d,1,null,'cash',gen_random_uuid());exception when raise_exception then if sqlerrm<>'injected_qa_receipt_failure' then raise;end if;denied:=true;end;
 execute 'drop trigger qa_test_fail_receipt on pharmacy_qa_private.debtor_cash_receipts';
 perform pg_temp.audit_check('cash failure aborts payment',denied);
 perform pg_temp.audit_check('cash failure leaves debt entries unchanged',(select count(*)=entries_before from pharmacy_qa_private.debtor_entries));
 perform pg_temp.audit_check('cash failure leaves receipts unchanged',(select count(*)=receipts_before from pharmacy_qa_private.debtor_cash_receipts));
 perform pg_temp.audit_check('rolled-back payment has no false success audit',(select count(*)=events_before from pharmacy_qa_private.audit_events));
 execute 'create trigger qa_test_fail_audit before insert on pharmacy_qa_private.audit_events for each row execute function pg_temp.fail_qa_audit()';
 denied:=false;begin perform public.qa_record_debtor_payment(d,1,null,'cash',gen_random_uuid());exception when raise_exception then if sqlerrm<>'injected_qa_audit_failure' then raise;end if;denied:=true;end;
 execute 'drop trigger qa_test_fail_audit on pharmacy_qa_private.audit_events';
 perform pg_temp.audit_check('audit failure blocks an unaudited payment',denied);
 perform pg_temp.audit_check('audit failure rolls back financial mutation',(select count(*)=entries_before from pharmacy_qa_private.debtor_entries));
 denied:=false;begin perform public.qa_record_debtor_payment(d,61,null,'cash',gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.audit_check('payment greater than remaining debt rejected',denied);
 perform public.qa_record_debtor_payment(d,60,'closing payment','cash',gen_random_uuid());
 perform pg_temp.audit_check('full payment closes balance exactly',(public.qa_debtor_ledger(d)->>'balance')::numeric=0);
 perform pg_temp.audit_check('ledger contains server running balances',not exists(select 1 from jsonb_array_elements(public.qa_debtor_ledger(d)->'transactions')x where not(x?'balance_after')));
 perform pg_temp.audit_check('payment audit identifies employee and amount',exists(select 1 from pharmacy_qa_private.audit_events where action='debtor_entries_insert' and actor_id=employee and details->'after'->>'id'=payment::text and (details->'after'->>'amount')::numeric=30));
 denied:=false;begin perform public.qa_security_audit();exception when insufficient_privilege then denied:=true;end;
 perform pg_temp.audit_check('employee cannot read security logs',denied);
 perform pg_temp.audit_check('snapshot does not expose audit or global financial report',not(public.qa_workspace_snapshot()?'audit_events') and not(public.qa_workspace_snapshot()?'report'));
 perform public.qa_record_workspace_access('debtors',gen_random_uuid());
 perform pg_temp.audit_check('navigation provenance cannot masquerade as server mutation',exists(select 1 from pharmacy_qa_private.audit_events where actor_id=employee and action='workspace_visit' and details->>'source'='client_reported_navigation'));
 denied:=false;begin perform public.qa_record_workspace_access('arbitrary forged action',gen_random_uuid());exception when invalid_parameter_value then denied:=true;end;
 perform pg_temp.audit_check('arbitrary client audit labels rejected',denied);
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);after_report:=public.qa_sandbox_report();
 select coalesce(sum((x->>'amount')::numeric),0) into cash_after from jsonb_array_elements(after_report->'balances')x where x->>'kind'='cash' and x->>'currency'='SYP';
 perform pg_temp.audit_check('cash report increases by cash collections only',cash_after-cash_before=90);
 perform pg_temp.audit_check('debt collections never inflate sales profit',after_report->'profit'=before_report->'profit');
 perform pg_temp.audit_check('cashbox shows debtor collection entry',exists(select 1 from jsonb_array_elements(after_report->'cash_entries')x where x->>'id'=payment::text and x->>'type'='debtor_payment' and (x->>'amount')::numeric=30));
 perform pg_temp.audit_check('manager can view audit trail',exists(select 1 from jsonb_array_elements(public.qa_security_audit(500))x where x->>'entity_id'=d::text and x->>'actor_role'='employee'));
 -- Exercise daily operations with the mandatory audit triggers enabled.
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 body:=jsonb_build_object('name','QA audit product','barcode','QA-AUDIT-'||product,'unit','box','reorder_level',1,'purchase_price',1,'sale_price',0,'parts_per_unit',10,'customer_visible',false,'sale_currency','USD');
 perform public.qa_save_workspace_product(null,body,'[]',product);
 perform pg_temp.audit_check('product creation is audited',exists(select 1 from pharmacy_qa_private.audit_events where action='catalog_insert' and entity_id=product::text and actor_id=employee));
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);perform public.qa_save_workspace_product(product,body||'{"sale_price":2}','[]',gen_random_uuid());
 perform set_config('request.jwt.claims',(claims->'employee')::text,true);
 operation_id:=public.qa_employee_execute_workspace('purchase_draft',jsonb_build_array(jsonb_build_object('product_id',product,'quantity',3,'bonus',0,'unit_cost',1,'discount',0,'expiry','2027-12-31')),'USD',gen_random_uuid());
 perform pg_temp.audit_check('purchase and inventory addition are audited',exists(select 1 from pharmacy_qa_private.audit_events where action='batches_insert' and actor_id=employee and details->'after'->>'product_id'=product::text));
 sale:=public.qa_employee_execute_workspace('sale',jsonb_build_array(jsonb_build_object('product_id',product,'quantity',1)),null,gen_random_uuid());
 perform pg_temp.audit_check('sale action and stock movement are audited',exists(select 1 from pharmacy_qa_private.audit_events where action='documents_insert' and actor_id=employee and details->'after'->>'kind'='sale' and details->'after'->>'product_id'=product::text));
 select doc.id into sale_doc from pharmacy_qa_private.documents doc join public.qa_employee_operations o on o.id=doc.request_id where o.payload->>'bundle_parent'=sale::text;
 return_req:=public.qa_submit_workspace_bundle('return_request',jsonb_build_array(jsonb_build_object('sale_id',sale_doc,'quantity',1)),null);
 perform pg_temp.audit_check('pending employee request preserves submitted quantity in audit',exists(select 1 from pharmacy_qa_private.audit_events where action='qa_employee_operations_insert' and actor_id=employee and (details->'request_data'->>'quantity')::numeric=1));
 perform set_config('request.jwt.claims',(claims->'manager')::text,true);perform public.qa_review_employee_operation(return_req,true);
 perform pg_temp.audit_check('manager approval is attributed to manager',exists(select 1 from pharmacy_qa_private.audit_events where action='qa_employee_operations_update' and actor_id=manager and entity_id=return_req::text and details->'after'->>'status'='approved'));
 perform set_config('request.jwt.claims',(claims->'support')::text,true);
 perform pg_temp.audit_check('support remains sanitized',(select array_agg(k order by k)=array['health','role'] from jsonb_object_keys(public.qa_workspace_snapshot())k));
end $$;
select jsonb_build_object('mode','rolled-back database tests with synthetic Auth users and claims; not HTTP/browser','passed',count(*),'results',jsonb_agg(to_jsonb(r))) result from qa_debtor_audit_results r;
rollback;
